use super::*;
use std::collections::HashSet;

const MAX_VISITED: usize = 100_000;
const MAX_BETA_STEPS: usize = 20_000;

fn app_parts(value: &T) -> (T, Vec<T>) {
    let mut head = value.clone();
    let mut args = Vec::new();
    while let Term::App(function, argument) = head.as_ref() {
        args.push(argument.clone());
        head = function.clone();
    }
    args.reverse();
    (head, args)
}

// Reduce only the head redexes generated by the closed difference-list
// builders. In particular, globals stay opaque and are never delta-reduced.
fn head_beta(mut value: T, kernel: &mut Kernel, budget: &mut usize) -> T {
    loop {
        let (head, args) = app_parts(&value);
        let Term::Lam(_, body) = head.as_ref() else {
            return value;
        };
        if args.is_empty() {
            return value;
        }
        *budget += 1;
        assert!(*budget <= MAX_BETA_STEPS, "beta step bound exceeded");
        let mut reduced = kernel.instantiate(body, &args[0], 0).unwrap();
        for arg in args.iter().skip(1) {
            reduced = term(Term::App(reduced, arg.clone()));
        }
        value = reduced;
    }
}

fn expanded_scalars(value: &str) -> Vec<u32> {
    let expanded = expand(value).unwrap();
    let (outer, outer_args) = app_parts(&expanded);
    assert!(
        matches!(outer.as_ref(), Term::Global(name, levels) if name == OF_LIST && levels.is_empty())
    );
    assert_eq!(outer_args.len(), 1);
    let mut kernel = Kernel::new();
    let mut budget = 0;
    let mut cursor = outer_args[0].clone();
    let mut scalars = Vec::new();
    for _ in 0..=value.chars().count() {
        cursor = head_beta(cursor, &mut kernel, &mut budget);
        let (head, args) = app_parts(&cursor);
        let Term::Global(name, levels) = head.as_ref() else {
            panic!("list head is not a global constructor")
        };
        assert!(levels.len() <= 1);
        if name == NIL {
            assert_eq!(args.len(), 1);
            return scalars;
        }
        assert_eq!(name, CONS);
        assert_eq!(args.len(), 3);
        let (char_head, char_args) = app_parts(&args[1]);
        assert!(
            matches!(char_head.as_ref(), Term::Global(name, levels) if name == OF_NAT && levels.is_empty())
        );
        assert_eq!(char_args.len(), 1);
        let Term::NatLiteral { family, value } = char_args[0].as_ref() else {
            panic!("Char.ofNat argument is not a natural literal")
        };
        assert_eq!(family, NAT);
        scalars.push(value.decimal().parse().unwrap());
        cursor = args[2].clone();
    }
    panic!("list traversal bound exceeded")
}

fn measured_depth(root: &T) -> (usize, usize, HashSet<usize>, usize) {
    let mut stack = vec![(root.clone(), 1usize)];
    let (mut deepest, mut visited, mut owned_node_bytes, mut owned_payload) = (0, 0, 0, 0);
    let mut seen = HashSet::new();
    while let Some((node, depth)) = stack.pop() {
        visited += 1;
        assert!(visited <= MAX_VISITED, "term traversal bound exceeded");
        deepest = deepest.max(depth);
        let ptr = Arc::as_ptr(&node) as usize;
        if seen.insert(ptr) {
            owned_node_bytes += std::mem::size_of::<Term>() + 2 * std::mem::size_of::<usize>();
            match node.as_ref() {
                Term::Global(name, _) => owned_payload += name.len(),
                Term::NatLiteral { family, value } => {
                    owned_payload += family.len() + value.decimal().len()
                }
                _ => {}
            }
        }
        let next = depth + 1;
        match node.as_ref() {
            Term::Sort(_) | Term::Var(_) | Term::Global(_, _) | Term::NatLiteral { .. } => {}
            Term::Pi(a, b) | Term::Lam(a, b) | Term::App(a, b) => {
                stack.push((a.clone(), next));
                stack.push((b.clone(), next));
            }
            other => panic!(
                "unexpected expansion term: {}",
                match other {
                    Term::Let(..) => "Let",
                    Term::Sigma(..) => "Sigma",
                    Term::Pair(..) => "Pair",
                    Term::First(..) => "First",
                    Term::Second(..) => "Second",
                    Term::Project { .. } => "Project",
                    Term::Eq(..) => "Eq",
                    Term::Refl(..) => "Refl",
                    Term::QuotType(..) => "QuotType",
                    Term::QuotMake(..) => "QuotMake",
                    Term::QuotLift { .. } => "QuotLift",
                    Term::QuotInduct { .. } => "QuotInduct",
                    Term::EqElim { .. } => "EqElim",
                    Term::Ctor { .. } => "Ctor",
                    Term::Induct { .. } => "Induct",
                    Term::MutualInduct { .. } => "MutualInduct",
                    Term::NestedInduct { .. } => "NestedInduct",
                    Term::SelfType => "SelfType",
                    Term::SelfAt(..) => "SelfAt",
                    Term::Recur(..) => "Recur",
                    _ => "unknown",
                }
            ),
        }
    }
    (deepest, visited, seen, owned_node_bytes + owned_payload)
}

#[test]
fn expands_exact_unicode_scalar_sequence_including_nul() {
    for value in ["", "Aq9", "é🦀", "a\0é🦀z"] {
        assert_eq!(
            expanded_scalars(value),
            value.chars().map(|ch| ch as u32).collect::<Vec<_>>()
        );
    }
}

#[test]
fn direct_and_balanced_expansions_beta_recover_ordered_lists() {
    for count in [0, 1, 7, 8, 9, 31, 32, 33, 65, 129] {
        let value = (0..count)
            .map(|i| char::from_u32(0x41 + (i % 26) as u32).unwrap())
            .collect::<String>();
        assert_eq!(
            expanded_scalars(&value),
            value.chars().map(|ch| ch as u32).collect::<Vec<_>>(),
            "scalar count {count}"
        );
    }
}

#[test]
fn byte_limit_is_in_bytes_while_depth_uses_unicode_scalars() {
    assert!(dimensions(&"x".repeat(MAX_STRING_BYTES)).is_ok());
    assert!(dimensions(&format!("{}x", "x".repeat(MAX_STRING_BYTES))).is_err());
    assert!(dimensions(&"é".repeat(MAX_STRING_BYTES / 2)).is_ok());
    assert!(dimensions(&format!("é{}", "x".repeat(MAX_STRING_BYTES - 1))).is_err());
    assert_eq!(dimensions("é🦀").unwrap().0, 6);
}

#[test]
fn dimensions_bound_expansion_depth_and_conservatively_account_owned_payload() {
    for count in [0, 1, 32, 33, 65, 129, 1024] {
        let value = "x".repeat(count);
        let (expected_depth, payload) = dimensions(&value).unwrap();
        let expanded = expand(&value).unwrap();
        let (actual_depth, _, _, _) = measured_depth(&expanded);
        assert_eq!(actual_depth, expected_depth, "scalar count {count}");
        assert!(payload > 0);
    }
    let value = "x".repeat(MAX_STRING_BYTES);
    let (expected_depth, payload) = dimensions(&value).unwrap();
    let expanded = expand(&value).unwrap();
    let (actual_depth, _, unique_nodes, accounted_owned) = measured_depth(&expanded);
    assert_eq!(actual_depth, expected_depth);
    assert!(actual_depth < 96);
    assert!(unique_nodes.len() <= MAX_VISITED);
    assert!(
        payload >= accounted_owned,
        "payload covers unique owned nodes, headers, names, and numerals"
    );
}
